import{_ as r,l,o as e,c as s,v as t,p as n,x as i,d as E,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"地方财政与转移支付","description":"","frontmatter":{"title":"地方财政与转移支付","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/local-fiscal-transfers.md","filePath":"econ/local-fiscal-transfers.md","lastUpdated":1789023840000}'),c={name:"econ/local-fiscal-transfers.md"};function p(B,a,h,u,_,T){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="地方财政与转移支付" tabindex="-1">地方财政与转移支付 <a class="header-anchor" href="#地方财政与转移支付" aria-label="Permalink to &quot;地方财政与转移支付&quot;">​</a></h1><div class="epigraph"><p>地方提供有空间范围的公共品，居民用脚投票；中央转移本为纠正外溢与纵向财力缺口，却可能把地方预算变成软约束，钱停在政府部门而不降税。</p><footer>—— Tiebout, A Pure Theory of Local Expenditures, JPE 1956；Oates, Fiscal Federalism, 1972；Hines 与飞纸效应文献；Kornai 软预算约束；对照 Atkinson–Stiglitz</footer></div><p><a href="/econ/sovereign-debt-sustain">上一课</a>把主权跨期预算写成 \\(r-g\\) 与盈余承诺。本课缺口是多级：地方不能印储备货币，常被限制发债，支出却落在教育、基础设施上。转移支付是中央对地方的 \\(s\\)，会改变地方的激励，而不只是改变会计上的 \\(b\\)。公共财政在此收束；下一课经济史用制度对照危机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Tiebout：社区差异化提供地方公共品，居民选区，类似市场显示偏好——前提是流动、多社区、无外溢。Oates 分权定理：地方信息更好时，地方提供更对准；全国性外溢（国防、再分配）留在中央。缺口是转移：纵向缺口（地方税基不够支出责任）用一般或专项补助来补。补助若增加地方公共支出的程度大于等价的居民增收入，就是飞纸：钱粘在公共部门。软预算：地方预期中央会救，于是事前过度借、过度承诺——Kornai 的软约束从企业搬到政府。主权课的多重均衡在地方变成「中央会不会救」。</p><h3 id="转移不是把地方变成中央出纳" tabindex="-1">转移不是把地方变成中央出纳 <a class="header-anchor" href="#转移不是把地方变成中央出纳" aria-label="Permalink to &quot;转移不是把地方变成中央出纳&quot;">​</a></h3><p>若每笔支出都由专项指定并全额配套，地方没有边际选择，Tiebout 与 Oates 的信息优势消失，免费搭车与寻租转到项目申报。一般补助保留边际，但再分配与外溢纠正变弱。设计要在「对准全国目标」与「保留地方边际」之间权衡，不是越多专项越「规范」。</p><p><span class="marginnote">飞纸效应的经验大小有争议，机制候选包括政治代理、专项的价格效应、以及居民对补助的财政幻觉。本课要的是激励方向，不是某一个 meta 回归的点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三笔账。(1) 地方公共品：可排他到社区则免费搭车轻于全国纯公共品，但仍有辖区间外溢。(2) 转移公式：总额、配套率、封顶，改变地方公共资金的边际价格。(3) 硬预算：破产程序、不救助承诺要可信；不可信则地方债是隐性主权债，上一课的 \\(b\\) 被低估。乘数：对地方的一次性转移，MPC 与漏出（买外地商品）决定地方 \\(Y\\) 动多少，与全国乘数不同。</p>',10)),(e(),n(d,null,{default:i(()=>[A(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOV%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E4%B8%BB%E6%9D%83%E8%B7%A8%E6%9C%9F%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20FED%5B%22%E5%A4%9A%E7%BA%A7%E9%A2%84%E7%AE%97%22%5D%0A%20%20FED%20--%3E%20TIE%5B%22Tiebout%20%E6%B5%81%E5%8A%A8%E6%98%BE%E7%A4%BA%22%5D%0A%20%20FED%20--%3E%20TR%5B%22%E8%BD%AC%E7%A7%BB%3A%20%E5%A4%96%E6%BA%A2%E4%B8%8E%E7%BA%B5%E5%90%91%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20TR%20--%3E%20SOFT%5B%22%E8%BD%AF%E7%BA%A6%E6%9D%9F%E5%88%99%E6%BF%80%E5%8A%B1%E6%89%AD%E6%9B%B2%22%5D%0A%20%20SOFT%20--%3E%20HIST%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E9%87%91%E6%9C%AC%E4%BD%8D%E4%B8%8E%E5%A4%A7%E8%90%A7%E6%9D%A1%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把土地财政或某一国的税制当普遍公式。机制是税基流动性、外溢与救助预期。资本税基比劳动更会跑，地方若靠流动性税基竞争，Oates 的「信息优势」会被竞次抵消——转移有时是为了阻止有害竞争，而不只是补缺口。专项的配套率过高，地方会为了把钱花完而选高成本项目，飞纸变成浪费而不是公共品。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>用脚投票把地方公共品的 MRS 显示在选址上，比全国自愿贡献好，因为排他到社区。外溢一出现，地方只对准内部 MRS，全国加总仍不足——转移或中央提供是把加总写回来。配套补助降低地方提供的边际成本，数量上升；收入补助只移动预算线，飞纸说数量升得比私人收入等价更多，代理问题是候选机制。软预算把地方的 \\(r\\) 变成「中央 implicit 担保的 \\(r\\)」，过度投资，危机时并入主权。</p><p>与社保：地方养老金缺口是隐性债的一层，中央若兜底，再分配在地区之间发生，漏桶多一截政治。户籍与流动限制削弱 Tiebout：不能用脚投票时，地方公共品更接近全国自愿供给失败，只是范围小一号。设计转移时要把流动摩擦写进去，不能默认美国式社区选择。</p><p><span class="marginnote">Oates 1972 的分权是信息与外溢的权衡。Kornai 的软约束是承诺问题。两套机制叠在转移支付上：设计补助公式时，同时问外溢与救助预期。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某国转移支付法条，不评估具体项目。公共财政领域课到此结束。经济史第一课用金本位对照：地方不能印金，主权在金本位下也不能随意印——约束形状相似，层级不同。后课默认：看见补助，先问专项还是一般、配套率、以及救助是否可信；不要把转移当成免费的 \\(G\\)。横向均等化若切断地方税基与支出的联系，Tiebout 显示偏好会弱掉一截。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>地方公共品靠流动与社区排他减轻免费搭车，外溢仍要中央。</li><li>转移纠正纵向缺口与外溢，也改变地方边际价格。</li><li>飞纸与软预算是代理和承诺失败，不是会计笔误。</li><li>地方隐性债可并入主权 \\(b\\)；救助预期是关键。</li><li>公共财政收束；下一课改用危机制度对照。</li><li>出处：Tiebout 1956；Oates 1972；飞纸文献；Kornai；Atkinson and Stiglitz。</li></ul>',9))])}const b=r(c,[["render",p]]);export{m as __pageData,b as default};
